using CustomCodeFramework.Core.Results;using CustomCodeFramework.Cqrs.Commands;using CustomCodeFramework.Persistence.Abstractions;using Dhole.Content.Application.Abstractions.Auditing;using Dhole.Content.Application.Abstractions.Cache;using Dhole.Content.Application.Abstractions.Repositories;using Dhole.Content.Application.Auditing;using Dhole.Content.Domain.Navigation.Entities;using Dhole.Content.Domain.Shared;namespace Dhole.Content.Application.Navigation.UpsertNavigationMenu;public sealed class UpsertNavigationMenuCommandHandler(INavigationMenuRepository repo,IContentAuditService audit,IContentCacheService cache,IUnitOfWork uow):ICommandHandler<UpsertNavigationMenuCommand,Result<Guid>>{public async Task<Result<Guid>> HandleAsync(UpsertNavigationMenuCommand c,CancellationToken ct=default){var site=string.IsNullOrWhiteSpace(c.SiteKey)?ContentConstants.DefaultSiteKey:c.SiteKey.Trim();var location=c.Location.Trim().ToLowerInvariant();var x=await repo.GetByLocationAsync(site,location,ct);object? before=null;if(x is null){x=NavigationMenu.Create(c.Name,location,site,c.ActorUserId);await repo.AddAsync(x,ct);}else before=ContentAuditSnapshots.From(x);x.Replace(c.Name,c.Items.Select(i=>(i.Label,i.Url,i.ContentId,i.ParentId,i.SortOrder,i.Target)),c.ActorUserId);await audit.PublishAsync(new ContentAuditEvent(ContentAuditEventTypes.MenuUpdated,before is null?ContentAuditActions.Created:ContentAuditActions.Updated,ContentAuditEntityTypes.NavigationMenu,x.Id,c.ActorUserId,Before:before,After:ContentAuditSnapshots.From(x)),ct);await uow.SaveChangesAsync(ct);await cache.RemoveMenuAsync(site,location,ct);return Result.Success(x.Id);}}
